// spec: skins
// Скины шахтёра: число и позолоченные, бонусы по числу скинов, стикеры (банки, множитель, справочник), требования достижений.
// Код по спеке oracle/specs/skins.md (правила 1–11, интерфейс). Данные — data/systems/skins.json; передаёт вызывающий: ядро само в файлы не ходит.
import { pow } from './num/libm.mjs';

function tableRows(t) {
  return t.rows.map((r) => Object.fromEntries(t.columns.map((c, i) => [c, r[i]])));
}

/** @param {object} skinsData содержимое data/systems/skins.json */
export function makeSkins(skinsData) {
  const C = skinsData.constants;
  const T = skinsData.tables;
  const eps = C.eps;
  const bonuses = tableRows(T.bonuses);
  const steps = tableRows(T.steps);
  const derived = tableRows(T.derived);
  const stickers = tableRows(T.stickers);
  const stickerCells = tableRows(T.stickerCells);
  const achievements = tableRows(T.achievements);

  // правила 1–2: сумма новых скинов (значение целиком) + костюмы (по 1); позолоченные — значения больше порога
  function counts(state) {
    let owned = 0;
    let gilded = 0;
    for (const v of state.new) {
      if (v - 0 > eps) owned += v;
      if (v - C['skins.gildedAbove'] > eps) gilded += 1;
    }
    for (const v of state.suit) {
      if (v - 0 > eps) owned += 1;
      if (v - C['skins.gildedAbove'] > eps) gilded += 1;
    }
    return { owned, gilded };
  }

  // правило 4
  function has(owned, k) {
    return k - owned <= eps;
  }

  // правило 5 suits-b: вставка шагов (как в suits)
  function rules(rulesData) {
    const columns = [...rulesData.tables.rules.columns];
    const ix = Object.fromEntries(columns.map((c, i) => [c, i]));
    const rows = rulesData.tables.rules.rows.map((r) => [...r]);
    for (const st of steps) {
      const own = rows.map((r, i) => i).filter((i) => rows[i][ix.cell] === st.cell);
      const hit = own.filter((i) => rows[i][ix.source] === st.source && rows[i][ix.row] === st.row);
      if (!hit.length) throw new Error(`skins: нет шага-якоря для ${st.cell}`);
      if (st.mode !== 'after') throw new Error(`skins: неизвестный режим ${st.mode}`);
      const num = rows[hit[0]][ix.step];
      let last = hit[0];
      for (const i of own) if (rows[i][ix.step] === num) last = i;
      const row = columns.map(() => null);
      row[ix.cell] = st.cell;
      row[ix.step] = num + 0.5;
      row[ix.op] = st.op;
      row[ix.ref] = st.ext;
      rows.splice(last + 1, 0, row);
    }
    return { ...rulesData, tables: { ...rulesData.tables, rules: { ...rulesData.tables.rules, columns, rows } } };
  }

  // правило 5: внешние значения строк с ext, бонус которых действует
  function externals(owned) {
    const out = {};
    for (const b of bonuses) if (b.ext && has(owned, b.skins)) out[b.ext] = b.value;
    return out;
  }

  function need(cells, name) {
    if (!(name in cells)) throw new Error(`skins: нет клетки ${name}`);
  }

  // правила 5, 8, 7 по порядку
  function apply(cells, owned, stickerCounts) {
    const out = { ...cells };
    const tierBest = new Map();
    let m = 1;
    for (const b of bonuses) {
      if (b.ext || !has(owned, b.skins)) continue;
      if (b.op === 'bankMul') { m = b.value; continue; }
      if (b.op === 'tier') {
        const prev = tierBest.get(b.cell);
        if (!prev || b.skins > prev.skins) tierBest.set(b.cell, b);
        continue;
      }
      need(out, b.cell);
      out[b.cell] = b.op === 'mul' ? out[b.cell] * b.value : out[b.cell] + b.value;
    }
    for (const [cell, b] of tierBest) {
      need(out, cell);
      out[cell] = out[cell] * b.value;
    }
    const cap = out['stat.stickerCap'];
    for (const s of stickerCells) {
      need(out, s.cell);
      const n = stickerCounts[s.sticker];
      if (s.op === 'bankCeil') out[s.cell] = Math.ceil((out[s.cell] + Math.min(n, cap)) * m);
      else if (s.op === 'bankFloor') out[s.cell] = Math.floor((out[s.cell] + Math.min(n, cap)) * m);
      else if (s.op === 'addRateMax') out[s.cell] = out[s.cell] + Math.min(n * s.rate, cap);
      else throw new Error(`skins: неизвестный вид ${s.op}`);
    }
    for (const d of derived) {
      need(out, d.cell);
      need(out, d.by);
      const x = out[d.cell] * out[d.by];
      out[d.cell] = d.round === 'halfUp' ? Math.floor(x + 0.5) : x;
    }
    return out;
  }

  // правило 9
  function stickerMulti(i, n, cap) {
    const s = stickers.find((r) => r.sticker === i);
    if (!s) throw new Error(`skins: нет стикера ${i}`);
    return 1 + s.rate * Math.min(n, cap);
  }

  // правило 10
  function sticker(i) {
    const s = stickers.find((r) => r.sticker === i);
    return s ? { name: s.name, rate: s.rate, kind: s.kind, desc: s.desc } : null;
  }

  // правило 11
  function achievementReq(j, L) {
    const a = achievements.find((r) => r.achievement === j);
    if (!a) throw new Error(`skins: нет достижения ${j}`);
    return a.base * pow(a.growth, L);
